Section HeadInit.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo CA c : Z).
  Let P := CA + PCLASS_SIZE * c.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 32 <= bv_unsigned sp.
  Hypothesis CR : 1 <= c <= 31.
  Hypothesis CAR : akobj CA 2592 /\ CA + 2592 <= aceil /\ CA mod 16 = 0.
  Hypothesis MC0 : rw_cells bsegs m (P + 4) [C4 (wz 0)].
  Hypothesis FAM : forall c', 1 <= c' <= 31 -> exists mc cs, rw_cells bsegs m (CA + 80 * c' + 4) [C4 mc] /\ rw_cells bsegs m (CA + 80 * c' + 8) [C8 cs].

  Let CAE : 4096 <= CA /\ CA + 2592 <= aceil. Proof. exact (akobj_env _ _ (proj1 CAR) ltac:(clear; lia)). Qed.   (* [comment removed for export] *)
  Theorem refill_head_init :
    evt bsegs (fun ms' => (exists t3' t4' t5', refill_head_post ra sp gp tp (wz 16) (wz 17) (wz 512) s0 s1 (Z_to_bv 64 16) (wz 15) (wz 1024) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6 F fc m
                             ((bv_unsigned sp - 32, bv_unsigned sp) :: icW CA)%Z lo CA P c ms')
                          /\ (forall c', 1 <= c' <= 31 -> rw_cells bsegs (ms_mem ms') (CA + 80 * c' + 4) [C4 (wz (max_count c'))]
                                                      /\ rw_cells bsegs (ms_mem ms') (CA + 80 * c' + 8) [C8 (wz (class_size c'))]))
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz CA) (wz P) (wz AINST) (wz c) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
